module cdc_reset_ctrlr #(
    parameter SYNC_STAGES = 2
)(
    input  a_clk_i,
    input  a_rst_ni,
    input  a_clear_i,
    output a_clear_o,
    input  a_clear_ack_i,
    output a_isolate_o,
    input  a_isolate_ack_i,
    input  b_clk_i,
    input  b_rst_ni,
    input  b_clear_i,
    output b_clear_o,
    input  b_clear_ack_i,
    output b_isolate_o,
    input  b_isolate_ack_i
);

reg [SYNC_STAGES-1:0] a_clear_sync;
reg [SYNC_STAGES-1:0] b_clear_sync;
reg [SYNC_STAGES-1:0] a_isolate_sync;
reg [SYNC_STAGES-1:0] b_isolate_sync;

reg a_clear_reg;
reg a_isolate_reg;
reg b_clear_reg;
reg b_isolate_reg;

reg a_clear_req;
reg b_clear_req;

always @(posedge a_clk_i or negedge a_rst_ni) begin
    if (!a_rst_ni) begin
        a_clear_sync <= {SYNC_STAGES{1'b0}};
        a_isolate_sync <= {SYNC_STAGES{1'b0}};
        a_clear_reg <= 1'b0;
        a_isolate_reg <= 1'b0;
        a_clear_req <= 1'b0;
    end else begin
        a_clear_sync[0] <= b_clear_i;
        for (int i = 1; i < SYNC_STAGES; i++) begin
            a_clear_sync[i] <= a_clear_sync[i-1];
        end
        a_isolate_sync[0] <= b_isolate_i;
        for (int i = 1; i < SYNC_STAGES; i++) begin
            a_isolate_sync[i] <= a_isolate_sync[i-1];
        end
        if (a_clear_i || a_clear_sync[SYNC_STAGES-1]) begin
            a_clear_req <= 1'b1;
        end else if (a_clear_ack_i) begin
            a_clear_req <= 1'b0;
        end
        if (a_clear_req && a_isolate_ack_i && b_isolate_sync[SYNC_STAGES-1]) begin
            a_clear_reg <= 1'b1;
        end else if (a_clear_ack_i) begin
            a_clear_reg <= 1'b0;
        end
        if (a_clear_req &&!a_isolate_reg) begin
            a_isolate_reg <= 1'b1;
        end else if (a_isolate_ack_i &&!a_clear_req) begin
            a_isolate_reg <= 1'b0;
        end
    end
end

always @(posedge b_clk_i or negedge b_rst_ni) begin
    if (!b_rst_ni) begin
        b_clear_sync <= {SYNC_STAGES{1'b0}};
        b_isolate_sync <= {SYNC_STAGES{1'b0}};
        b_clear_reg <= 1'b0;
        b_isolate_reg <= 1'b0;
        b_clear_req <= 1'b0;
    end else begin
        b_clear_sync[0] <= a_clear_i;
        for (int i = 1; i < SYNC_STAGES; i++) begin
            b_clear_sync[i] <= b_clear_sync[i-1];
        end
        b_isolate_sync[0] <= a_isolate_i;
        for (int i = 1; i < SYNC_STAGES; i++) begin
            b_isolate_sync[i] <= b_isolate_sync[i-1];
        end
        if (b_clear_i || b_clear_sync[SYNC_STAGES-1]) begin
            b_clear_req <= 1'b1;
        end else if (b_clear_ack_i) begin
            b_clear_req <= 1'b0;
        end
        if (b_clear_req && b_isolate_ack_i && a_isolate_sync[SYNC_STAGES-1]) begin
            b_clear_reg <= 1'b1;
        end else if (b_clear_ack_i) begin
            b_clear_reg <= 1'b0;
        end
        if (b_clear_req &&!b_isolate_reg) begin
            b_isolate_reg <= 1'b1;
        end else if (b_isolate_ack_i &&!b_clear_req) begin
            b_isolate_reg <= 1'b0;
        end
    end
end

assign a_clear_o = a_clear_reg;
assign a_isolate_o = a_isolate_reg;
assign b_clear_o = b_clear_reg;
assign b_isolate_o = b_isolate_reg;

endmodule
